CONDORCET = ("from math import comb\n\n"
             "def majority_correct(p, n):\n"
             "    \"\"\"n тәуелсіз дауыс беруші (n тақ), әрқайсысы p ықтималдықпен дұрыс\"\"\"\n"
             "    return sum(comb(n, k) * p ** k * (1 - p) ** (n - k) for k in range(n // 2 + 1, n + 1))\n\n"
             "for p in (0.45, 0.6, 0.75):\n"
             "    row = '  '.join(f'n={n}: {majority_correct(p, n):.3f}' for n in (1, 3, 7, 15))\n"
             "    print(f'p = {p}: {row}')\n\n"
             "# Шешімнің қайтымдылығы бойынша процесс\n"
             "decisions = [('кітапхананың кіші нұсқасын жаңарту', True), ('дерекқорды ауыстыру', False), ('API атауы', False), ('логтың форматы', True)]\n"
             "for d, reversible in decisions:\n"
             "    print(f'{d:36} ->', 'жылдам: бір адам шешеді, кейін түзетеміз' if reversible else 'баяу: дизайн құжаты, кең талқылау, ADR')")

