DORA = ("from datetime import date\n\n"
        "deploys = [  # (күн, коммиттен шығаруға дейінгі сағат, инцидент тудырды ма, қалпына келтіру минуты)\n"
        "    (date(2026, 10, 1), 20, False, 0), (date(2026, 10, 2), 6, False, 0), (date(2026, 10, 2), 30, True, 45),\n"
        "    (date(2026, 10, 5), 4, False, 0), (date(2026, 10, 6), 12, False, 0), (date(2026, 10, 8), 8, True, 15),\n"
        "    (date(2026, 10, 9), 5, False, 0), (date(2026, 10, 12), 9, False, 0),\n"
        "]\n"
        "days = (deploys[-1][0] - deploys[0][0]).days + 1\n"
        "lead = sorted(h for _, h, _, _ in deploys)\n"
        "fails = [m for _, _, bad, m in deploys if bad]\n"
        "print(f'шығару жиілігі: {len(deploys) / days * 7:.1f} рет/апта')\n"
        "print(f'өзгеріс жеткізу уақыты (медиана): {lead[len(lead) // 2]} сағ')\n"
        "print(f'өзгерістердің сәтсіздік үлесі: {len(fails) / len(deploys):.0%}')\n"
        "print(f'қалпына келтіру уақыты (орташа): {sum(fails) / len(fails):.0f} мин')\n\n"
        "# Пакет өлшемі: әр өзгеріс тәуелсіз q ықтималдықпен қате болса\n"
        "q = 0.05\n"
        "for b in (1, 5, 20):\n"
        "    print(f'{b:2} өзгеріс бір шығарылымда: шығарылым сәтсіз {1 - (1 - q) ** b:.0%}')")

