CANARY = ("import math, random\n\n"
          "users = 100_000\n"
          "base_err, bad_err = 0.002, 0.02        # жаңа нұсқа қате болса, қате 10 есе өседі\n"
          "rng = random.Random(21)\n\n"
          "def canary(fraction, requests):\n"
          "    \"\"\"трафиктің fraction үлесі жаңа нұсқаға; z-тест арқылы шешім\"\"\"\n"
          "    n_new = int(requests * fraction)\n"
          "    n_old = requests - n_new\n"
          "    x_new = sum(rng.random() < bad_err for _ in range(n_new))\n"
          "    x_old = sum(rng.random() < base_err for _ in range(n_old))\n"
          "    p = (x_new + x_old) / requests\n"
          "    se = math.sqrt(p * (1 - p) * (1 / n_new + 1 / n_old))\n"
          "    z = (x_new / n_new - x_old / n_old) / se\n"
          "    return z, x_new\n\n"
          "for f in (0.01, 0.05):\n"
          "    z, affected = canary(f, 20000)\n"
          "    print(f'canary {f:.0%}: z = {z:.1f} ->', 'тоқтату' if z > 3 else 'жалғастыру', f'| қате көрген пайдаланушылар: {affected}')\n"
          "print('canary-сыз бірден бәріне: қате көретіндер шамамен', int(20000 * bad_err))")

