STRAT = ("initiatives = {  # атауы: (құны - инженер-апта, пайдасы - келісілген бірлік)\n"
         "    'бақылау және SLO':        (6, 40),\n"
         "    'деплой автоматтандыру':   (8, 55),\n"
         "    'төлемді модульге бөлу':   (12, 60),\n"
         "    'жаңа мобильді экран':     (5, 25),\n"
         "    'дерекқорды жаңарту':      (10, 35),\n"
         "    'онбординг құжаттары':     (3, 18),\n"
         "}\n"
         "capacity = 26\n\n"
         "def best_portfolio(items, cap):\n"
         "    \"\"\"0/1 рюкзак: динамикалық бағдарламалау\"\"\"\n"
         "    names = list(items)\n"
         "    best = [[0] * (cap + 1) for _ in range(len(names) + 1)]\n"
         "    for i, n in enumerate(names, 1):\n"
         "        c, v = items[n]\n"
         "        for w in range(cap + 1):\n"
         "            best[i][w] = best[i - 1][w]\n"
         "            if c <= w:\n"
         "                best[i][w] = max(best[i][w], best[i - 1][w - c] + v)\n"
         "    chosen, w = [], cap\n"
         "    for i in range(len(names), 0, -1):\n"
         "        if best[i][w] != best[i - 1][w]:\n"
         "            chosen.append(names[i - 1])\n"
         "            w -= items[names[i - 1]][0]\n"
         "    return best[-1][cap], sorted(chosen)\n\n"
         "value, chosen = best_portfolio(initiatives, capacity)\n"
         "print('оңтайлы портфель:', chosen, '-> пайда', value)\n"
         "greedy = sorted(initiatives, key=lambda n: -initiatives[n][1] / initiatives[n][0])\n"
         "used = gv = 0\n"
         "for n in greedy:\n"
         "    if used + initiatives[n][0] <= capacity:\n"
         "        used += initiatives[n][0]; gv += initiatives[n][1]\n"
         "print('ашкөз (пайда/құн) таңдау пайдасы:', gv)")

